abstract class ShapeProcessor<T> { abstract forCircle(c: Circle): T; }
abstract class UnionProcessor<T> extends ShapeProcessor<T> { // extended visitor
  abstract forUnion(u: UnionShape): T; }
class UnionShape implements Shape {
  constructor(readonly a: Shape, readonly b: Shape) {}
  process<T>(p: ShapeProcessor<T>): T {
    if (p instanceof UnionProcessor) return p.forUnion(this);  // runtime check: a class, not a shape
    throw new Error(`no handler for UnionShape in ${p.constructor.name}`);
  }
}
class UnionArea extends Area implements UnionProcessor<number> {
  forUnion(u: UnionShape) { return u.a.process(this) + u.b.process(this); }
}
